window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-c2464b7c469dda50"]={"versions": [{"id": "FIG-c2464b7c469dda50", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des AUTOSAR-Metamodells auf M2-Ebene (Software Component Template). Es stellt die grundlegende Vererbungs- und Assoziationshierarchie von Datentypen dar, insbesondere die Spezialisierung von <code>Datatype</code> in primitive und zusammengesetzte Typen sowie die Anbindung von Software-Datendefinitionseigenschaften (<code>SwDataDefProps</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>Datatype</code>: Abstrakte Basisklasse, spezialisiert als <code>ARElement</code> mit dem Stereotyp <code>«atpType»</code>.\n</li><li><code>PrimitiveType</code>: Spezialisierung von <code>Datatype</code> mit Stereotyp <code>«atpType»</code>, dient als atomarer Typ. Besitzt eine Kompositionsbeziehung zu <code>SwDataDefProps</code> (Rolle <code>+swDataDefProps</code>, Multiplizität <code>0..1</code>).\n</li><li><code>CompositeType</code>: Spezialisierung von <code>Datatype</code> mit Stereotyp <code>«atpType»</code> für komplexe bzw. strukturierte Datentypen.\n</li><li><code>SwDataDefProps</code>: Eigenschaftscontainer mit Stereotyp <code>IsSyscond</code>. Enthält Referenzen und Kompositionen zur weiteren Typcharakterisierung:\n<ul class=\"fig-list\"><li>Assoziation <code>+baseType</code> (<code>0..1</code>) zu <code>SwBaseType</code> (Typkategorie <code>BaseType</code>).\n</li><li>Assoziation <code>+compuMethod</code> (<code>0..1</code>) zu <code>CompuMethod</code> (spezialisiert als <code>ARElement</code>).\n</li><li>Komposition <code>+invalidValue</code> (<code>0..1</code>) zu <code>PrimitiveSpecification</code> (spezialisiert als <code>ValueSpecification</code>).\n</li></ul>\n</li><li><code>SwBaseType</code>: Konkreter Basistyp (<code>BaseType</code>), der die maschinennahe Datentypdefinition vorgibt.\n</li><li><code>CompuMethod</code>: Berechnungsvorschrift bzw. Skalierungs-/Umrechnungsmethode zur Abbildung zwischen internen und physikalischen Werten.\n</li><li><code>PrimitiveSpecification</code>: Spezifikation von Literal-/Ersatzwerten, hier zur Festlegung des ungültigen Werts (<code>+invalidValue</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Sequenzabläufe oder Laufzeitinteraktionen. Die Beziehungen beschreiben strukturelle Abhängigkeiten zur Entwurfs- und Konfigurationszeit: Ein <code>PrimitiveType</code> kapselt optionale <code>SwDataDefProps</code>, welche wiederum Verweise auf Berechnungsverfahren (<code>CompuMethod</code>), Plattform-Basistypen (<code>SwBaseType</code>) sowie ungültige Werte (<code>PrimitiveSpecification</code>) bündeln.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Modellierung regelt die normative Definition primitiver Datentypen im AUTOSAR-Template. Entwickler und Generatoren müssen berücksichtigen, dass <code>swDataDefProps</code>, <code>baseType</code>, <code>compuMethod</code> und <code>invalidValue</code> jeweils mit der Multiplizität <code>0..1</code> optional sind. Ein <code>PrimitiveType</code> erfordert für seine semantische und maschinelle Interpretation in nachgelagerten Phasen (RTE-Generierung, A2L/ASAM-Export) in der Regel die konsistente Auflösung der referenzierten <code>BaseType</code>- und <code>CompuMethod</code>-Elemente.</p>"}, {"id": "FIG-c77a20c91b84dd14", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des AUTOSAR-Metamodells auf M2-Ebene (Software Component Template). Es stellt die grundlegende Vererbungs- und Assoziationshierarchie von Datentypen dar, insbesondere die Spezialisierung von <code>Datatype</code> in primitive und zusammengesetzte Typen sowie die Anbindung von Software-Datendefinitionseigenschaften (<code>SwDataDefProps</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>Datatype</code>: Abstrakte Basisklasse, spezialisiert als <code>ARElement</code> mit dem Stereotyp <code>«atpType»</code>.\n</li><li><code>PrimitiveType</code>: Spezialisierung von <code>Datatype</code> mit Stereotyp <code>«atpType»</code>, dient als atomarer Typ. Besitzt eine Kompositionsbeziehung zu <code>SwDataDefProps</code> (Rolle <code>+swDataDefProps</code>, Multiplizität <code>0..1</code>).\n</li><li><code>CompositeType</code>: Spezialisierung von <code>Datatype</code> mit Stereotyp <code>«atpType»</code> für komplexe bzw. strukturierte Datentypen.\n</li><li><code>SwDataDefProps</code>: Eigenschaftscontainer mit Stereotyp <code>IsSyscond</code>. Enthält Referenzen und Kompositionen zur weiteren Typcharakterisierung:\n<ul class=\"fig-list\"><li>Assoziation <code>+baseType</code> (<code>0..1</code>) zu <code>SwBaseType</code> (Typkategorie <code>BaseType</code>).\n</li><li>Assoziation <code>+compuMethod</code> (<code>0..1</code>) zu <code>CompuMethod</code> (spezialisiert als <code>ARElement</code>).\n</li><li>Komposition <code>+invalidValue</code> (<code>0..1</code>) zu <code>PrimitiveSpecification</code> (spezialisiert als <code>ValueSpecification</code>).\n</li></ul>\n</li><li><code>SwBaseType</code>: Konkreter Basistyp (<code>BaseType</code>), der die maschinennahe Datentypdefinition vorgibt.\n</li><li><code>CompuMethod</code>: Berechnungsvorschrift bzw. Skalierungs-/Umrechnungsmethode zur Abbildung zwischen internen und physikalischen Werten.\n</li><li><code>PrimitiveSpecification</code>: Spezifikation von Literal-/Ersatzwerten, hier zur Festlegung des ungültigen Werts (<code>+invalidValue</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Sequenzabläufe oder Laufzeitinteraktionen. Die Beziehungen beschreiben strukturelle Abhängigkeiten zur Entwurfs- und Konfigurationszeit: Ein <code>PrimitiveType</code> kapselt optionale <code>SwDataDefProps</code>, welche wiederum Verweise auf Berechnungsverfahren (<code>CompuMethod</code>), Plattform-Basistypen (<code>SwBaseType</code>) sowie ungültige Werte (<code>PrimitiveSpecification</code>) bündeln.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Modellierung regelt die normative Definition primitiver Datentypen im AUTOSAR-Template. Entwickler und Generatoren müssen berücksichtigen, dass <code>swDataDefProps</code>, <code>baseType</code>, <code>compuMethod</code> und <code>invalidValue</code> jeweils mit der Multiplizität <code>0..1</code> optional sind. Ein <code>PrimitiveType</code> erfordert für seine semantische und maschinelle Interpretation in nachgelagerten Phasen (RTE-Generierung, A2L/ASAM-Export) in der Regel die konsistente Auflösung der referenzierten <code>BaseType</code>- und <code>CompuMethod</code>-Elemente.</p>"}], "trans": [{"from": "FIG-c2464b7c469dda50", "to": "FIG-c77a20c91b84dd14", "fr": "R3.1.5", "tr": "R3.2.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
